input.command:
firecrawl scrape "https://chromewebstore.google.com/search/tab%20manager?itemTypes=EXTENSION" --max-age 0 -o /dev/null >/dev/null 2>&1; firecrawl interact --timeout 280 --code '
let n=0;for (let i=0;i<40;i++){ const b=page.getByRole("button",{name:/load more/i}); if(!(await b.count())) break; await b.first().click(); n++; await page.waitForTimeout(1500);}
const links=await page.$$eval("a[href*=\"/detail/\"]",as=>[...new Set(as.map(a=>a.href))]);
console.log("CLICKS",n,"COUNT",links.length);console.log(JSON.stringify(links));' -o .firecrawl/links2.txt; grep -o 'CLICKS.*' .firecrawl/links2.txt | head -2; firecrawl interact stop >/dev/null 2>&1

